/* ================= COPY LINK & DOWNLOAD — ONE WORKING WAY, ONE VISIBLE SIGN =================
   Owner's direction (Nov 23 2026): "make the copy link and download
   functionable — and a little sign so people see, for instance
   'copied link'". Two problems made them feel broken before:
   - Copy used ONLY navigator.clipboard, which the app's webview /
   iframe often refuses (no permission, not a secure context) — the
   tap then did nothing at all, with no sign either way.
   - Download revoked the file's URL the instant it was clicked, so
   some browsers cancelled the save before it started; and the only
   feedback was a line of text far from the button.
   Now EVERY copy and download in the app goes through the helpers
   below: copy tries the clipboard API, then the textarea fallback,
   and a download keeps its URL alive for a few seconds after the
   click. Both end by raising the little ActionSign pill (bottom
   centre, check + words — "Link copied ✓", "Download started ✓"),
   so the person always SEES that it worked — or, when a copy truly
   can't happen on their device, a sign saying so while the link
   itself stays on screen to copy by hand. */
export function showActionSign(message: string, ok = true) {
  try { window.dispatchEvent(new CustomEvent("vs-action-sign", { detail: { message, ok } })); } catch { /* no window listener yet */ }
}
/** The same little sign, but honest about a failure: amber, with a "!". */
export function showActionProblem(message: string) {
  showActionSign(message, false);
}

export async function copyTextRobust(text: string): Promise<boolean> {
  if (!text) return false;
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch { /* clipboard refused — fall through to the textarea way */ }
  try {
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.setAttribute("readonly", "");
    ta.style.position = "fixed";
    ta.style.top = "0";
    ta.style.left = "0";
    ta.style.width = "2em";
    ta.style.height = "2em";
    ta.style.opacity = "0.01";
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    try { ta.setSelectionRange(0, text.length); } catch { /* older webviews */ }
    const ok = document.execCommand("copy");
    document.body.removeChild(ta);
    return ok;
  } catch { return false; }
}

/** Copy + the visible sign in one call. Returns whether it copied. */
export async function copyWithSign(text: string, successMessage = "Link copied ✓"): Promise<boolean> {
  const ok = await copyTextRobust(text);
  if (ok) showActionSign(successMessage); else showActionProblem("Copy didn't work here — the link stays on screen so you can copy it by hand");
  return ok;
}

/** Start a real file download from a Blob, keeping the URL alive
 *  long enough for the browser to actually take the file, then
 *  raise the sign. Returns whether the download was started. */
export function downloadBlobWithSign(blob: Blob, filename: string, successMessage = "Download started ✓ — check your downloads"): boolean {
  try {
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    a.rel = "noopener";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.setTimeout(() => { try { URL.revokeObjectURL(url); } catch { /* already gone */ } }, 4000);
    showActionSign(successMessage);
    return true;
  } catch {
    showActionProblem("Download didn't start here — try again, or open ViceSunshine in your browser to save the file");
    return false;
  }
}

/* The little sign itself: one pill, mounted once by the App shell,
   listening for "vs-action-sign". A new sign replaces the old one
   and restarts its timer; it fades after ~2.6 seconds. */
function ActionSign() {
  const [sign, setSign] = useState<{ id: number; message: string; ok: boolean } | null>(null);
  useEffect(() => {
    let timer = 0;
    const onSign = (e: Event) => {
      const detail = (e as CustomEvent<{ message: string; ok: boolean }>).detail;
      const message = typeof detail === "string" ? detail : detail?.message;
      if (!message) return;
      setSign({ id: Date.now(), message, ok: typeof detail === "string" ? true : detail.ok !== false });
      window.clearTimeout(timer);
      timer = window.setTimeout(() => setSign(null), 2600);
    };
    window.addEventListener("vs-action-sign", onSign);
    return () => { window.removeEventListener("vs-action-sign", onSign); window.clearTimeout(timer); };
  }, []);
  if (!sign) return null;
  return createPortal(
    <div
      key={sign.id}
      role="status"
      aria-live="polite"
      className="pointer-events-none fixed left-1/2 z-[400] flex w-max max-w-[calc(100vw-2rem)] -translate-x-1/2 items-center gap-2 rounded-[22px] py-2.5 pl-3 pr-4 shadow-2xl"
      style={{ bottom: "calc(env(safe-area-inset-bottom, 0px) + 92px)", background: "#17102B", border: "1px solid rgba(255,255,255,0.22)", color: "#fff" }}
    >
      <span className="flex h-6 w-6 flex-none items-center justify-center rounded-full" style={{ background: sign.ok ? "#0E9F6E" : "#E8A33D" }} aria-hidden="true">
        {sign.ok ? (
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M4.5 12.5l5 5L19.5 7" /></svg>
        ) : (
          <span className="text-[14px] font-black leading-none text-white">!</span>
        )}
      </span>
      <span className="text-[13.5px] font-bold leading-snug">{uiT(sign.message)}</span>
    </div>,
    document.body,
  );
}

/* ===================== PHOTO UPLOAD OPTIMIZER =====================
   Performance fix (owner's report, Nov 21 2026: "pictures take
   really long to load"). Phone photos used to be uploaded exactly
   as shot — a 3–12 MB full-resolution file — stored that way, and
   then re-downloaded at full size by every screen that showed the
   picture (profile, story ball, feed, highlights). That is why the
   profile picture and the story preview crawled.

   Now every photo is resized ON THE DEVICE before upload: capped
   at a sensible longest edge for where it will be shown (512px for
   avatars, which never render bigger than ~120px; 1600px for
   banners, event pictures and feed/story photos, which is full
   quality at story/post size) and re-encoded compactly (JPEG at
   0.85 for opaque photos; transparent pictures stay PNG so their
   transparency is never flattened). A typical phone photo lands
   at ~150–450 KB instead of 3–12 MB —
   roughly 10–30x faster to upload AND to load everywhere after,
   with no visible quality loss at the sizes the site displays.

   Anything that is not a plain photo (videos, GIFs, files the
   browser cannot decode, already-small pictures) passes through
   untouched, and any failure falls back to the original file, so
   an upload can never break because of the optimizer. */
async function downscaleImageBlob(blob: Blob, maxEdge: number): Promise<Blob> {
  if (!blob.type.startsWith("image/") || blob.type === "image/gif") return blob;
  try {
    const objUrl = URL.createObjectURL(blob);
    try {
      const img = await new Promise<HTMLImageElement>((resolve, reject) => {
        const i = new Image();
        i.onload = () => resolve(i);
        i.onerror = () => reject(new Error("image decode failed"));
        i.src = objUrl;
      });
      const longest = Math.max(img.naturalWidth, img.naturalHeight);
      if (!longest) return blob;
      const scale = Math.min(1, maxEdge / longest);
      // Already small in both dimensions and bytes: keep the
      // original file exactly as it is (PNG transparency and all).
      if (scale >= 1 && blob.size <= 400_000) return blob;
      const w = Math.max(1, Math.round(img.naturalWidth * scale));
      const h = Math.max(1, Math.round(img.naturalHeight * scale));
      const canvas = document.createElement("canvas");
      canvas.width = w;
      canvas.height = h;
      const c2d = canvas.getContext("2d");
      if (!c2d) return blob;
      c2d.drawImage(img, 0, 0, w, h);
      // Transparency is preserved, never flattened: probe a tiny
      // copy for real alpha, and if the picture has any, keep it
      // as PNG (the upload safety check reads PNG fine). Only
      // fully opaque pictures — phone photos, screenshots — take
      // the compact JPEG path.
      let hasAlpha = false;
      try {
        const probe = document.createElement("canvas");
        probe.width = 32;
        probe.height = 32;
        const pctx = probe.getContext("2d");
        if (pctx) {
          pctx.drawImage(img, 0, 0, 32, 32);
          const pd = pctx.getImageData(0, 0, 32, 32).data;
          for (let i = 3; i < pd.length; i += 4) { if (pd[i]! < 250) { hasAlpha = true; break; } }
        }
      } catch { /* probe failed — treat as opaque, the common case */ }
      const out = hasAlpha
        ? await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, "image/png"))
        : await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, "image/jpeg", 0.85));
      return out && out.size < blob.size ? out : blob;
    } finally {
      URL.revokeObjectURL(objUrl);
    }
  } catch {
    return blob;
  }
}

function blobToBase64(blob: Blob): Promise<{ dataBase64: string; mimeType: string }> {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => {
      const s = typeof r.result === "string" ? r.result : "";
      const comma = s.indexOf(",");
      if (comma < 0) { reject(new Error("Could not read that file.")); return; }
      resolve({ dataBase64: s.slice(comma + 1), mimeType: blob.type || "image/jpeg" });
    };
    r.onerror = () => reject(new Error("Could not read that file."));
    r.readAsDataURL(blob);
  });
}

/** Read a picked file ready for an upload action: photos are
 *  downscaled to `maxEdge` first (see above); everything else is
 *  read as-is. Drop-in replacement for fileToBase64 at photo
 *  upload sites. */
async function optimizedPhotoUpload(file: File | Blob, maxEdge: number): Promise<{ dataBase64: string; mimeType: string }> {
  const finalBlob = file.type.startsWith("image/") ? await downscaleImageBlob(file, maxEdge) : file;
  return blobToBase64(finalBlob);
}

/* Videos are shrunk ON THE DEVICE before upload (owner's
   direction, Nov 22 2026 — "there shouldn't be a limit in
   size"): a normal phone video is far too big to send as it
   comes off the camera (60 seconds can be well over 100 MB,
   and the upload sends the file as base64 text), so any video
   over the send threshold is re-recorded here at at most 720p
   with its bitrate sized to land around 9 MB however long it
   runs — the video twin of optimizedPhotoUpload. The re-record
   plays the clip into a canvas and records that with
   MediaRecorder, audio included; it runs in real time, so a
   long clip takes about as long as the clip itself, and the
   composer shows the progress while it runs. A device that
   cannot re-record (no MediaRecorder, an unreadable file, a
   play that stalls) hands back the original file — the
   server's storage ceiling sits far above a normal clip, so
   even then a normal video still posts. Only a re-record that
   played to the end AND came out smaller is ever used, so a
   failed shrink can never publish a cut-off clip. */
const VIDEO_SEND_MAX_BYTES = 8 * 1024 * 1024;

async function compressVideoForUpload(blob: Blob, onProgress?: (frac: number) => void): Promise<Blob> {
  if (blob.size <= VIDEO_SEND_MAX_BYTES) return blob;
  if (typeof MediaRecorder === "undefined") return blob;
  const mimeType = ["video/webm;codecs=vp9,opus", "video/webm;codecs=vp8,opus", "video/webm", "video/mp4"].find((t) => {
    try { return MediaRecorder.isTypeSupported(t); } catch { return false; }
  });
  if (!mimeType) return blob;
  const url = URL.createObjectURL(blob);
  try {
    return await new Promise<Blob>((resolve) => {
      const video = document.createElement("video");
      video.preload = "auto";
      video.playsInline = true;
      video.src = url;
      let settled = false;
      let watchdog = 0;
      const finish = (out: Blob | null, completed: boolean) => {
        if (settled) return;
        settled = true;
        window.clearTimeout(watchdog);
        try { video.pause(); } catch { /* already stopped */ }
        resolve(completed && out && out.size > 0 && out.size < blob.size ? out : blob);
      };
      video.onerror = () => finish(null, false);
      video.onloadedmetadata = () => {
        try {
          const duration = Number.isFinite(video.duration) && video.duration > 0 ? video.duration : 60;
          const longEdge = Math.max(video.videoWidth || 0, video.videoHeight || 0);
          const scale = longEdge > 1280 ? 1280 / longEdge : 1;
          const w = Math.max(2, Math.round(((video.videoWidth || 640) * scale) / 2) * 2);
          const h = Math.max(2, Math.round(((video.videoHeight || 640) * scale) / 2) * 2);
          const canvas = document.createElement("canvas");
          canvas.width = w;
          canvas.height = h;
          const c = canvas.getContext("2d");
          if (!c) { finish(null, false); return; }
          const stream = canvas.captureStream(30);
          // Audio rides along through an AudioContext into the
          // recorded stream; a silent gain keeps the graph
          // running (so the clip keeps playing) without the
          // phone blaring the video out while it shrinks.
          let audioCtx: AudioContext | null = null;
          try {
            const AC = window.AudioContext ?? (window as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
            if (AC) {
              audioCtx = new AC();
              const srcNode = audioCtx.createMediaElementSource(video);
              const destNode = audioCtx.createMediaStreamDestination();
              srcNode.connect(destNode);
              const mute = audioCtx.createGain();
              mute.gain.value = 0;
              srcNode.connect(mute);
              mute.connect(audioCtx.destination);
              for (const track of destNode.stream.getAudioTracks()) stream.addTrack(track);
              void audioCtx.resume().catch(() => { /* sound is best-effort */ });
            }
          } catch { /* video-only is still a working shrink */ }
          // Bitrate sized to the clip: about 9 MB of video
          // however long it runs, never above ~2.5 Mbps.
          const targetTotalBps = Math.min(2_600_000, Math.max(500_000, Math.floor((9 * 8 * 1024 * 1024) / duration)));
          const recorder = new MediaRecorder(stream, {
            mimeType,
            videoBitsPerSecond: Math.max(400_000, targetTotalBps - 96_000),
            audioBitsPerSecond: 96_000,
          });
          const chunks: Blob[] = [];
          recorder.ondataavailable = (e) => { if (e.data.size > 0) chunks.push(e.data); };
          recorder.onstop = () => {
            if (audioCtx) void audioCtx.close().catch(() => { /* already closed */ });
            finish(
              new Blob(chunks, { type: mimeType.split(";")[0] ?? "video/webm" }),
              video.ended || video.currentTime >= duration - 0.35,
            );
          };
          let raf = 0;
          const draw = () => {
            if (settled) return;
            c.drawImage(video, 0, 0, w, h);
            onProgress?.(Math.min(1, video.currentTime / duration));
            if (!video.ended) raf = requestAnimationFrame(draw);
          };
          video.onended = () => {
            cancelAnimationFrame(raf);
            onProgress?.(1);
            try { recorder.stop(); } catch { finish(null, false); }
          };
          // Safety net: a stalled play must never hang the
          // composer — stop shortly after the clip's own length
          // and let finish() judge what was captured.
          watchdog = window.setTimeout(() => {
            try { recorder.stop(); } catch { finish(null, false); }
          }, (duration + 20) * 1000);
          recorder.start(1000);
          draw();
          void video.play().catch(() => finish(null, false));
        } catch {
          finish(null, false);
        }
      };
    });
  } finally {
    URL.revokeObjectURL(url);
  }
}

/** Read a picked video ready for an upload action: shrunk on
 *  the device first when it is big (see above). Drop-in
 *  replacement for blobToBase64 at video upload sites. */
async function preparedVideoUpload(blob: Blob, onProgress?: (frac: number) => void): Promise<{ dataBase64: string; mimeType: string }> {
  return blobToBase64(await compressVideoForUpload(blob, onProgress));
}

/* The one plain-words translation for upload size failures: a
   raw schema message ("Data base64: Must be … characters or
   fewer") must never be what a player reads — Ben hit exactly
   that on the New post screen (Nov 22 2026). Anything that
   smells like the raw size cap becomes one plain sentence;
   the server's own plain sentences pass through untouched. */
function plainUploadError(e: unknown): string {
  const msg = e instanceof Error ? e.message : String(e ?? "");
  if (/^data base64\b|characters or fewer/i.test(msg)) {
    return "This video is too big to share — try a shorter clip.";
  }
  return msg || "Upload failed — try again.";
}

/* One-time self-heal for photos stored BEFORE the optimizer
   existed: they sit in storage at full phone resolution and load
   slowly on every screen. When the owner opens their own profile,
   an oversized stored avatar/banner is quietly re-saved at the
   optimized size through the normal upload actions (so the server
   safety check runs exactly as for a fresh upload) — same picture,
   much smaller file, fast loads from then on. Each URL is tried
   at most once per session, and a picture already within its cap
   and a sane byte size is left completely alone, so this always
   terminates. Any failure just leaves the current picture as is. */
const healedPhotoUrls = new Set<string>();

async function optimizedStoredPhoto(url: string, maxEdge: number): Promise<{ dataBase64: string; mimeType: string } | null> {
  try {
    const res = await fetch(url);
    if (!res.ok) return null;
    const blob = await res.blob();
    if (!blob.type.startsWith("image/") || blob.type === "image/gif") return null;
    const out = await downscaleImageBlob(blob, maxEdge);
    if (out === blob || out.size >= blob.size) return null;
    return await blobToBase64(out);
  } catch {
    return null;
  }
}

/* How big is a stored photo, WITHOUT downloading it? A HEAD
   request reads the Content-Length header only, so checking a
   picture costs a round trip and no picture bytes. Returns null
   when the size cannot be learned this way (no header, request
   refused) — the caller then falls back to downloading, exactly
   as before. The self-heal below asks this first: a picture
   already within a sane byte size is loading as fast as it can,
   and pulling the whole file down on every profile visit just
   to confirm that was competing with the very images the player
   is looking at. */
async function storedPhotoByteSize(url: string): Promise<number | null> {
  try {
    const res = await fetch(url, { method: "HEAD" });
    if (!res.ok) return null;
    const len = Number(res.headers.get("content-length") ?? "");
    return Number.isFinite(len) && len > 0 ? len : null;
  } catch {
    return null;
  }
}

/* Paint a just-saved photo NOW from the copy already on the
   device, then swap in the server's copy once it has really
   loaded. An upload returns the moment the server has the
   picture — but the profile then used to point its <img> at the
   brand-new server URL and wait for a full fresh download of a
   picture the device already had in hand, which on a phone is
   exactly when the broken-image "?" placeholder sat on the
   profile for ages (owner's report, Nov 21 2026). The upload
   handlers therefore write the uploaded bytes straight into the
   profile caches as a data URL (instant paint, no network) and
   register the swap here: the server URL is preloaded in the
   background, and only when it has genuinely loaded does it
   replace the local copy — so the swap itself can never flash
   the placeholder either. If the preload fails, the local copy
   simply stays for the session; the next natural refetch
   restores the canonical URL. */
const serverPhotoSwaps = new Set<string>();
function swapToServerPhotoWhenLoaded(serverUrl: string, apply: (url: string) => void): void {
  if (!serverUrl || serverUrl.startsWith("data:") || serverPhotoSwaps.has(serverUrl)) return;
  serverPhotoSwaps.add(serverUrl);
  const img = new Image();
  img.onload = () => { serverPhotoSwaps.delete(serverUrl); apply(serverUrl); };
  img.onerror = () => { serverPhotoSwaps.delete(serverUrl); };
  img.src = serverUrl;
}

