const ADSENSE_PUBLISHER_ID = "";

type AdFormat = "infeed" | "vertical" | "sidebar" | "leaderboard" | "mobileBanner" | "mediumRect" | "largeRect" | "halfPage" | "responsive";

const AD_META: Record<AdFormat, { h: number; size: string; maxW?: number }> = {
  leaderboard: { h: 90, size: "728 × 90 · Leaderboard", maxW: 728 },
  mobileBanner: { h: 100, size: "320 × 100 · Large mobile banner" },
  mediumRect: { h: 250, size: "300 × 250 · Medium rectangle", maxW: 300 },
  largeRect: { h: 280, size: "336 × 280 · Large rectangle", maxW: 336 },
  halfPage: { h: 600, size: "300 × 600 · Half page", maxW: 300 },
  responsive: { h: 110, size: "Responsive" },
  infeed: { h: 120, size: "Responsive · in-feed" },
  vertical: { h: 420, size: "300 × 600 · Half page" },
  sidebar: { h: 96, size: "300 × 250 · Medium rectangle" },
};

function AdSlot({
  slot,
  format = "leaderboard",
  phoneFormat,
  only,
  premium,
  flush = false,
}: {
  slot: string;
  format?: AdFormat;
  /** The format this same spot serves on phone widths (owner's
      direction, Nov 22 2026: the phone layout differs from the
      laptop because of the size — e.g. a 336x280 large rectangle
      in a desktop list serves as the 320x100 large mobile banner
      on a phone). Defaults to the leaderboard → mobileBanner
      collapse for leaderboards, the desktop format otherwise. */
  phoneFormat?: AdFormat;
  /** Restrict the spot to one device class: "phone" renders only
      on phone widths, "desktop" only on wider screens. */
  only?: "phone" | "desktop";
  premium: boolean;
  flush?: boolean;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const live = ADSENSE_PUBLISHER_ID.trim().length > 0;
  // Responsive sizing (what a real responsive AdSense unit does):
  // on phone widths a 728x90 leaderboard serves as the 320x100
  // large mobile banner instead, so the strip stays thin and never
  // wraps into a tall block.
  const [narrow, setNarrow] = useState(() => typeof window !== "undefined" && typeof window.matchMedia === "function" && window.matchMedia("(max-width: 640px)").matches);
  useEffect(() => {
    const mq = window.matchMedia("(max-width: 640px)");
    const fn = () => setNarrow(mq.matches);
    mq.addEventListener?.("change", fn);
    return () => mq.removeEventListener?.("change", fn);
  }, []);
  // Device split (owner's direction, Nov 22 2026): the same spot
  // serves a different size per device — on a phone a placement
  // uses its phoneFormat when one is set (falling back to the
  // leaderboard → large-mobile-banner collapse), and an
  // `only`-restricted spot renders on its own device class only.
  const offDevice = (only === "phone" && !narrow) || (only === "desktop" && narrow);
  const effFormat: AdFormat = narrow ? (phoneFormat ?? (format === "leaderboard" ? "mobileBanner" : format)) : format;
  useEffect(() => {
    if (!live || premium || offDevice || !ref.current) return;
    const el = ref.current;
    if (el.dataset.loaded) return;
    el.dataset.loaded = "1";
    const s = document.createElement("script");
    s.async = true;
    s.crossOrigin = "anonymous";
    s.src = `https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${ADSENSE_PUBLISHER_ID}`;
    document.head.appendChild(s);
  }, [live, premium, offDevice]);
  // Premium members never see ads — anywhere on the site. A spot
  // restricted to the other device class renders nothing either.
  if (premium || offDevice) return null;
  const meta = AD_META[effFormat];
  const h = meta.h;
  // Invisible placeholder (owner's direction, Nov 23 2026 —
  // supersedes the Nov 22 faint-panel rule): while no AdSense
  // publisher ID is set, every ad spot renders NOTHING at all —
  // no panel, no "Ad" pill, no reserved empty space — so the
  // site looks completely ad-free until real ads go live. The
  // placements stay wired in the layout, so the day the
  // publisher ID is set, each real ad unit renders in its spot
  // with no code change. Premium members never reach the live
  // branch either (the return above), so for them every ad
  // space stays gone completely even once ads are live.
  if (!live) return null;
  const liveFormat = effFormat === "mediumRect" || effFormat === "largeRect" ? "rectangle" : effFormat === "halfPage" ? "vertical" : effFormat === "vertical" ? "fluid" : effFormat === "leaderboard" || effFormat === "mobileBanner" ? "horizontal" : "auto";
  return (
    <div ref={ref} className={`${flush ? "" : effFormat === "leaderboard" || effFormat === "mobileBanner" ? "my-3" : "my-4"} mx-auto w-full`} style={{ minHeight: h, maxWidth: meta.maxW }} aria-label={`Advertisement (${slot}) — ${meta.size}`}>
      <ins
        className="adsbygoogle"
        style={{ display: "block", minHeight: h }}
        data-ad-client={ADSENSE_PUBLISHER_ID}
        data-ad-slot={slot}
        data-ad-format={liveFormat}
        data-full-width-responsive="true"
      />
    </div>
  );
}

