export function uiLanguageName(code: string): string {
  return UI_LANGUAGES.find((l) => l.code === code)?.name ?? code;
}
// The live translation state: a module store so every uiT(…)
// call reads the current map, and useUiLangTick() re-renders the
// chrome when a new language's strings land.
let uiLangStrings: Record<string, string> = {};
let uiLangVersion = 0;
const uiLangListeners = new Set<() => void>();
function setUiLangStrings(strings: Record<string, string>) {
  uiLangStrings = strings;
  uiLangVersion += 1;
  uiLangListeners.forEach((f) => f());
}
export function uiT(s: string): string {
  return uiLangStrings[s] ?? s;
}
export function useUiLangTick(): number {
  return useSyncExternalStore(
    (f) => { uiLangListeners.add(f); return () => { uiLangListeners.delete(f); }; },
    () => uiLangVersion,
    () => 0,
  );
}
// Device copy of each language's finished strings: picking a
// language you have used on this device — or reopening the app
// in a non-English language — applies the saved map immediately,
// with no wait for the server; the server copy (shared by every
// device) refreshes it in the background.
const UI_STRINGS_CACHE_PREFIX = "vs-ui-strings-";
export function loadCachedUiStrings(code: string): Record<string, string> {
  try {
    const raw = window.localStorage.getItem(UI_STRINGS_CACHE_PREFIX + code);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as Record<string, string>;
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch { return {}; }
}
export function saveCachedUiStrings(code: string, strings: Record<string, string>) {
  try { window.localStorage.setItem(UI_STRINGS_CACHE_PREFIX + code, JSON.stringify(strings)); } catch { /* storage unavailable or full — the server cache still holds it */ }
}
// Background top-up for a language whose translation is still
// filling in: each call makes the server translate the next
// missing chunks and caches them; every finished batch is pushed
// into the shell's query and the device copy, so the remaining
// English strings swap over on their own — no second pick needed.
async function refillUiTranslations(qc: ReturnType<typeof useQueryClient>, code: string) {
  for (let i = 0; i < 5; i++) {
    // A short pause between rounds: a burst of translation
    // calls can hit the model's rate limit, and spacing the
    // retries is what lets the last chunks land.
    if (i > 0) await new Promise((r) => setTimeout(r, 4000));
    try {
      const res = await api.getUiTranslations({ language: code });
      if (!res || res.language !== code) return;
      if (Object.keys(res.strings).length > 0) {
        qc.setQueryData(["ui-translations", code], res);
        saveCachedUiStrings(code, res.strings);
      }
      if (res.complete) return;
    } catch { return; }
  }
}

