    const RANK: Record<string, number> = { Leader: 5, "Co-Leader": 4, Elder: 3, Member: 2, Recruit: 1 };
    const myRank = RANK[myCrewRole] ?? 0;
    const canManage = m.clanMemberId > 0 && myRank > (RANK[m.role] ?? 0) && (myCrewRole === "Leader" || myCrewRole === "Co-Leader" || myCrewRole === "Elder");
    const canMute = group.isLeader || (myCrewRole === "Co-Leader" && m.role !== "Leader");
    if (!canManage && !canMute) return null;
    const ORDER = ["Recruit", "Member", "Elder", "Co-Leader", "Leader"];
    const idx = ORDER.indexOf(m.role);
