  const eventChatRefetchRef = useRef(false);
  useEffect(() => {
    if (!pendingEventChatId || eventChatHandled || !convs.data) return;
    const g = (convs.data.groups ?? []).find((x) => x.kind === "event" && x.eventId === pendingEventChatId);
    if (g) {
      setEventChatHandled(true);
      setMsgTab("crew");
      openGroup(g.groupId);
      return;
    }
    if (!eventChatRefetchRef.current) {
      eventChatRefetchRef.current = true;
      void convs.refetch();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pendingEventChatId, eventChatHandled, convs.data]);
  // Resolve the crew-page hand-off (see pendingCrewChatId
  // above): once the conversation list is in, find this crew's
