      let top = placement === "below" ? rect.bottom + 8 : rect.top - 6;
      if (left + W > window.innerWidth - 12) left = Math.max(12, placement === "below" ? window.innerWidth - W - 12 : rect.left - W - 10);
      if (top + H > window.innerHeight - 12) top = Math.max(12, window.innerHeight - H - 12);
